INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.73.0',
  '2026-08-05',
  'Свои правила у групп товаров, группировка «Товаров», фикс даты в старых чеках',
  E'«Товары и цены» теперь сгруппированы по категориям, у каждой свой итог.\n\nУ групп видно правила: слова встроенного словаря и свои слова, которые можно добавлять и удалять. Свои проверяются раньше встроенных — ими же можно перекрыть словарь. Свою группу завести можно там же: отдельной сущности «группа» нет, группа — это категория, к которой добавлены слова, и дальше она наполняется сама. Порядок: ручная разметка → свои слова → встроенный словарь → «Не разобрано».\n\nИсправлено: в письмах 2024 года дата доставки записана иначе («10/13/2024 2:24:54 PM» вместо «2026-08-04 17:53»), разбор её не понимал, и покупки двухлетней давности ложились сегодняшним числом — то есть в текущий месяц отчёта. Теперь понимаются оба формата, а у разобранного письма появилась кнопка «Перечитать письмо»: она перечитывает чек новым разбором и подтягивает за ним дату и сумму траты.',
  E'Свои словарные правила — finance_word_rules (миграция 0094), проверяются ДО встроенного словаря в Importer.Classify. Полный порядок источников: manual → word → rule → пусто. Любое изменение правил вызывает ClassifyAll, иначе настройка не трогала бы уже разобранные чеки (та же ошибка, что чинилась в 2.72.1). Экран групп отдаёт слова встроенного словаря как есть: без них непонятно, почему товар уехал именно туда.\n\nФикс даты: reDate заменён на reDateLine + список шаблонов. В шаблонах однозначные «1/2/2006» не случайны — с ними Go разбирает и «10/13/2024», а с «01/02/2006» только двузначные. Непонятая дата не роняет разбор: чек важнее даты, но и выдавать сегодняшний день за дату покупки нельзя.\n\nRefreshMailReceipt обновляет чек и позиции и ПОДТЯГИВАЕТ созданную трату (spent_on, amount): иначе чек и деньги разъехались бы. Доступен как parse с refresh=true.\n\nПроверено: письмо старого формата принято с датой 2024-10-13, трата записана тем же числом; перечитывание уже разобранного чека возвращает refreshed=true, обычный повтор по-прежнему 409. Своё слово «wafer» увело вафли в новую категорию (пересобрано 3 чека), слово «beer» перекрыло встроенный словарь и увело пиво, при этом квас, размеченный руками, остался на месте — приоритет соблюдён. Дубль слова → 409.'
);
-- +goose StatementEnd

